options.incomingScript:
function mapToDittoProtocolMsg(headers, textPayload, bytePayload, contentType) {
  var jsonPayload = JSON.parse(textPayload);
  if (!jsonPayload.data || !jsonPayload.data.devs || jsonPayload.data.devs.length === 0) {
    return null;
  }
  var dev = jsonPayload.data.devs[0];
  var thingId = dev.devUid;
  var features = {};
  for (var key in dev.devPars) {
    if (dev.devPars.hasOwnProperty(key)) {
      var lastUnderscore = key.lastIndexOf('_');
      if (lastUnderscore !== -1) {
        var featureName = key.substring(0, lastUnderscore);
        var propertyName = key.substring(lastUnderscore + 1);
        if (!features[featureName]) {
          features[featureName] = {};
        }
        features[featureName][propertyName] = dev.devPars[key];
      }
    }
  }
  var messages = [];
  for (var featureName in features) {
    if (features.hasOwnProperty(featureName)) {
      messages.push(Ditto.buildDittoProtocolMsg(
        'cz.riot',
        thingId,
        'things',
        'twin',
        'commands',
        'modify',
        '/features/' + featureName + '/properties',
        headers,
        features[featureName]
      ));
    }
  }
  return messages;
}

options.outgoingScript:
function mapFromDittoProtocolMsg(namespace, id, group, channel, criterion, action, path, dittoHeaders, value, status, extra) {
  var pathParts = path.split('/');
  var featureId = pathParts.length > 2 ? pathParts[2] : 'unknown';
  var commandName = pathParts.length > 5 ? pathParts[5] : action;
  var payload = {
    command: commandName,
    feature: featureId,
    value: value
  };
  return Ditto.buildExternalMsg(
    dittoHeaders,
    JSON.stringify(payload),
    null,
    'application/json'
  );
}
